All the main operations of the tool calling features are logged at the <code>DEBUG</code> level. You can enable the logging by setting the log level to <code>DEBUG</code> for the <code>org.springframework.ai</code> package.
---
/**
 * Auto-configuration for common tool calling features of {@link ChatModel}.
 *
 * @author Thomas Vitale
 * @author Christian Tzolov
 * @author Daniel Garnier-Moiroux
 * @since 1.0.0
 */
@AutoConfiguration
@ConditionalOnClass(ChatModel.class)
@EnableConfigurationProperties(ToolCallingProperties.class)
public class ToolCallingAutoConfiguration {

    private static final Logger logger = LoggerFactory.getLogger(ToolCallingAutoConfiguration.class);

    /**
     * The default {@link ToolCallbackResolver} resolves tools by name for methods,
     * functions, and {@link ToolCallbackProvider} beans.
     * <p>
     * MCP providers are excluded, to avoid initializing them early with #listTools().
     */
    @Bean
    @ConditionalOnMissingBean
    ToolCallbackResolver toolCallbackResolver(// @formatter:off
    GenericApplicationContext applicationContext, List<ToolCallback> toolCallbacks, // Deprecated in favor of the tcbProviders. Kept for backward compatibility.
    ObjectProvider<List<ToolCallbackProvider>> tcbProviderList, ObjectProvider<ToolCallbackProvider> tcbProviders) {
        // @formatter:on
        List<ToolCallback> allFunctionAndToolCallbacks = new ArrayList<>(toolCallbacks);
        // Merge ToolCallbackProviders from both ObjectProviders.
        List<ToolCallbackProvider> totalToolCallbackProviders = new ArrayList<>(tcbProviderList.stream().flatMap(List::stream).toList());
        totalToolCallbackProviders.addAll(tcbProviders.stream().toList());
        // De-duplicate ToolCallbackProviders
        totalToolCallbackProviders = totalToolCallbackProviders.stream().distinct().toList();
        totalToolCallbackProviders.stream().filter(pr -> !isMcpToolCallbackProvider(ResolvableType.forInstance(pr))).map(pr -> List.of(pr.getToolCallbacks())).forEach(allFunctionAndToolCallbacks::addAll);
        var staticToolCallbackResolver = new StaticToolCallbackResolver(allFunctionAndToolCallbacks);
        var springBeanToolCallbackResolver = SpringBeanToolCallbackResolver.builder().applicationContext(applicationContext).build();
        return new DelegatingToolCallbackResolver(List.of(staticToolCallbackResolver, springBeanToolCallbackResolver));
    }

    private static boolean isMcpToolCallbackProvider(ResolvableType type) {
        if (type.getType().getTypeName().equals("org.springframework.ai.mcp.SyncMcpToolCallbackProvider") || type.getType().getTypeName().equals("org.springframework.ai.mcp.AsyncMcpToolCallbackProvider")) {
            return true;
        }
        var superType = type.getSuperType();
        return superType != ResolvableType.NONE && isMcpToolCallbackProvider(superType);
    }

    @Bean
    @ConditionalOnMissingBean
    ToolExecutionExceptionProcessor toolExecutionExceptionProcessor(ToolCallingProperties properties) {
        ArrayList<Class<? extends RuntimeException>> rethrownExceptions = new ArrayList<>();
        // ClientAuthorizationException is used by Spring Security in oauth2 flows,
        // for example with ServletOAuth2AuthorizedClientExchangeFilterFunction and
        // OAuth2ClientHttpRequestInterceptor.
        Class<? extends RuntimeException> oauth2Exception = getClassOrNull("org.springframework.security.oauth2.client.ClientAuthorizationException");
        if (oauth2Exception != null) {
            rethrownExceptions.add(oauth2Exception);
        }
        return DefaultToolExecutionExceptionProcessor.builder().alwaysThrow(properties.isThrowExceptionOnError()).rethrowExceptions(rethrownExceptions).build();
    }

    @Bean
    @ConditionalOnMissingBean
    ToolCallingManager toolCallingManager(ToolCallbackResolver toolCallbackResolver, ToolExecutionExceptionProcessor toolExecutionExceptionProcessor, ObjectProvider<ObservationRegistry> observationRegistry, ObjectProvider<ToolCallingObservationConvention> observationConvention) {
        var toolCallingManager = ToolCallingManager.builder().observationRegistry(observationRegistry.getIfUnique(() -> ObservationRegistry.NOOP)).toolCallbackResolver(toolCallbackResolver).toolExecutionExceptionProcessor(toolExecutionExceptionProcessor).build();
        observationConvention.ifAvailable(toolCallingManager::setObservationConvention);
        return toolCallingManager;
    }

    @Bean
    @ConditionalOnMissingBean
    @ConditionalOnProperty(prefix = ToolCallingProperties.CONFIG_PREFIX + ".observations", name = "include-content", havingValue = "true")
    ToolCallingContentObservationFilter toolCallingContentObservationFilter() {
        logger.warn("You have enabled the inclusion of the tool call arguments and result in the observations, with the risk of exposing sensitive or private information. Please, be careful!");
        return new ToolCallingContentObservationFilter();
    }

    private static Class<? extends RuntimeException> getClassOrNull(String className) {
        try {
            Class<?> clazz = ClassUtils.forName(className, null);
            if (RuntimeException.class.isAssignableFrom(clazz)) {
                return (Class<? extends RuntimeException>) clazz;
            } else {
                logger.debug("Class {} is not a subclass of RuntimeException", className);
            }
        } catch (ClassNotFoundException e) {
            logger.debug("Cannot load class: {}", className);
        } catch (Exception e) {
            logger.debug("Error loading class: {}", className, e);
        }
        return null;
    }
}
